begin;
insert into public.cefr_builtin_bank(seed_key,payload)
select item->>'seedKey',item-'seedKey' from (select $cefr_mock${"title":"Multilevel Mock 01 · Neighbourhood library","description":"Original mashq varianti: neighbourhood library. 35 Listening, 35 Reading, 3 Writing va 8 Speaking topshirig‘i. Rasmiy test savollari emas.","level":"B1–C1","format":"multilevel","rightsConfirmed":true,"seedKey":"sinfquiz-multilevel-1","sections":[{"skill":"listening","minutes":45,"parts":[{"id":"listening-p1","title":"Short announcements","text":"Listen to eight short messages. Choose the best answer for each.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-1-part-1.mp3","imageUrl":"","questions":[{"id":"m1-l1-1","type":"choice","text":"When does the meeting begin?","options":["10:30","09:45","12:00"],"answers":["10:30"],"explanation":"The announcement says: The first message said 09:45, but the neighbourhood library meeting now starts at 10:30."},{"id":"m1-l1-2","type":"choice","text":"Where will people meet?","options":["the town hall","the railway café","Riverside Library"],"answers":["Riverside Library"],"explanation":"The announcement says: We are meeting at Riverside Library. Please do not wait at the old entrance."},{"id":"m1-l1-3","type":"choice","text":"What should visitors bring?","options":["a camera","a notebook","a printed ticket"],"answers":["a notebook"],"explanation":"The announcement says: Before you leave home, remember to bring a notebook. Other equipment is provided."},{"id":"m1-l1-4","type":"choice","text":"What is the last day to register?","options":["Wednesday","the following weekend","the day after the event"],"answers":["Wednesday"],"explanation":"The announcement says: You can sign up until Wednesday. We cannot add names at the door."},{"id":"m1-l1-5","type":"choice","text":"How much is admission?","options":["five pounds","ten pounds","free"],"answers":["free"],"explanation":"The announcement says: Admission is free. The amount covers the materials, and there is no extra charge."},{"id":"m1-l1-6","type":"choice","text":"Who can answer questions?","options":["the driver","Mina","the caretaker"],"answers":["Mina"],"explanation":"The announcement says: If you have a question, ask for Mina at the information desk."},{"id":"m1-l1-7","type":"choice","text":"What did the team decide to do?","options":["move the discussion to the ground floor","cancel the entire project","ignore the difficulty"],"answers":["move the discussion to the ground floor"],"explanation":"The announcement says: Because the lift was unavailable, the team decided to move the discussion to the ground floor."},{"id":"m1-l1-8","type":"choice","text":"What is the main purpose?","options":["to sell more tickets","to replace every volunteer","sharing books across generations"],"answers":["sharing books across generations"],"explanation":"The announcement says: We are doing this to support sharing books across generations, not simply to advertise the event."}]},{"id":"listening-p2","title":"Briefing notes","text":"Listen to the briefing. Complete the notes with one word or number.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-1-part-2.mp3","imageUrl":"","questions":[{"id":"m1-l2-1","type":"text","text":"Which day is the briefing held? Write ONE word or number.","options":[],"answers":["Thursday"],"explanation":"The briefing explicitly gives Thursday."},{"id":"m1-l2-2","type":"text","text":"What time does the briefing start? Write ONE word or number.","options":[],"answers":["10:30"],"explanation":"The briefing explicitly gives 10:30."},{"id":"m1-l2-3","type":"text","text":"Who leads the first session? Write ONE word or number.","options":[],"answers":["Mina"],"explanation":"The briefing explicitly gives Mina."},{"id":"m1-l2-4","type":"text","text":"What is the registration deadline? Write ONE word or number.","options":[],"answers":["Wednesday"],"explanation":"The briefing explicitly gives Wednesday."},{"id":"m1-l2-5","type":"text","text":"How many entries were recorded? Write ONE word or number.","options":[],"answers":["26"],"explanation":"The briefing explicitly gives 26."},{"id":"m1-l2-6","type":"text","text":"Which word describes the main concern? Write ONE word or number.","options":[],"answers":["accessibility"],"explanation":"The briefing explicitly gives accessibility."}]},{"id":"listening-p3","title":"Four speakers","text":"Match four speakers with the main ideas. Two options are extra.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-1-part-3.mp3","imageUrl":"","questions":[{"id":"m1-l3-1","type":"choice","text":"Match speaker 1 with the main idea.","options":["Learning from a setback","Cautious optimism about a result","Planning the next stage","Finding a sponsor","Rejecting the whole project","Personal motivation"],"answers":["Personal motivation"],"explanation":"Speaker 1 focuses on personal motivation."},{"id":"m1-l3-2","type":"choice","text":"Match speaker 2 with the main idea.","options":["Cautious optimism about a result","Planning the next stage","Finding a sponsor","Rejecting the whole project","Personal motivation","Learning from a setback"],"answers":["Learning from a setback"],"explanation":"Speaker 2 focuses on learning from a setback."},{"id":"m1-l3-3","type":"choice","text":"Match speaker 3 with the main idea.","options":["Planning the next stage","Finding a sponsor","Rejecting the whole project","Personal motivation","Learning from a setback","Cautious optimism about a result"],"answers":["Cautious optimism about a result"],"explanation":"Speaker 3 focuses on cautious optimism about a result."},{"id":"m1-l3-4","type":"choice","text":"Match speaker 4 with the main idea.","options":["Finding a sponsor","Rejecting the whole project","Personal motivation","Learning from a setback","Cautious optimism about a result","Planning the next stage"],"answers":["Planning the next stage"],"explanation":"Speaker 4 focuses on planning the next stage."}]},{"id":"listening-p4","title":"Responding to requests","text":"Match each request to the response. Three options are extra.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-1-part-4.mp3","imageUrl":"","questions":[{"id":"m1-l4-1","type":"choice","text":"Which response was given to a visitor who cannot reach the upper floor?","options":["Check the revised schedule","Help plan a follow-up session","Explain the sample limitation","Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room"],"answers":["Move activities to an accessible room"],"explanation":"The announcement connects this request with “move activities to an accessible room”."},{"id":"m1-l4-2","type":"choice","text":"Which response was given to a volunteer who needs to know the arrival time?","options":["Help plan a follow-up session","Explain the sample limitation","Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule"],"answers":["Check the revised schedule"],"explanation":"The announcement connects this request with “check the revised schedule”."},{"id":"m1-l4-3","type":"choice","text":"Which response was given to someone who wants the project to continue?","options":["Explain the sample limitation","Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session"],"answers":["Help plan a follow-up session"],"explanation":"The announcement connects this request with “help plan a follow-up session”."},{"id":"m1-l4-4","type":"choice","text":"Which response was given to a researcher questioning the findings?","options":["Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation"],"answers":["Explain the sample limitation"],"explanation":"The announcement connects this request with “explain the sample limitation”."},{"id":"m1-l4-5","type":"choice","text":"Which response was given to a participant with an item to bring?","options":["Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation","Read the equipment list"],"answers":["Read the equipment list"],"explanation":"The announcement connects this request with “read the equipment list”."}]},{"id":"listening-p5","title":"Three conversations","text":"Listen to three conversations. Answer two questions about each.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-1-part-5.mp3","imageUrl":"","questions":[{"id":"m1-l5-1","type":"choice","text":"Why is the speaker cautious?","options":["There was no trial.","The report was lost.","the survey covered just one afternoon"],"answers":["the survey covered just one afternoon"],"explanation":"Conversation 1 states this clearly."},{"id":"m1-l5-2","type":"choice","text":"What does the speaker recommend?","options":["buying a larger room","another trial","closing the project"],"answers":["another trial"],"explanation":"Conversation 1 states this clearly."},{"id":"m1-l5-3","type":"choice","text":"Which option does the second speaker prefer?","options":["neither option","a lending shelf","a digital catalogue"],"answers":["a lending shelf"],"explanation":"Conversation 2 states this clearly."},{"id":"m1-l5-4","type":"choice","text":"Why does the speaker prefer it?","options":["sharing books across generations","it is the oldest option","it needs no volunteers"],"answers":["sharing books across generations"],"explanation":"Conversation 2 states this clearly."},{"id":"m1-l5-5","type":"choice","text":"Who will speak?","options":["Mina","the driver","the caretaker"],"answers":["Mina"],"explanation":"Conversation 3 states this clearly."},{"id":"m1-l5-6","type":"choice","text":"Why did the plan change?","options":["a lack of interest","a change in the weather forecast","the lift was unavailable"],"answers":["the lift was unavailable"],"explanation":"Conversation 3 states this clearly."}]},{"id":"listening-p6","title":"Project lecture","text":"Listen to the lecture and write one word or number for each answer.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-1-part-6.mp3","imageUrl":"","questions":[{"id":"m1-l6-1","type":"text","text":"What do the collected records form? Write ONE word or number.","options":[],"answers":["evidence"],"explanation":"The lecture uses the word evidence."},{"id":"m1-l6-2","type":"text","text":"What is the total highlighted in the report? Write ONE word or number.","options":[],"answers":["26"],"explanation":"The lecture uses the word 26."},{"id":"m1-l6-3","type":"text","text":"Which word describes the key idea? Write ONE word or number.","options":[],"answers":["accessibility"],"explanation":"The lecture uses the word accessibility."},{"id":"m1-l6-4","type":"text","text":"What did the team ask visitors for? Write ONE word or number.","options":[],"answers":["feedback"],"explanation":"The lecture uses the word feedback."},{"id":"m1-l6-5","type":"text","text":"What must be understood behind a result? Write ONE word or number.","options":[],"answers":["conditions"],"explanation":"The lecture uses the word conditions."},{"id":"m1-l6-6","type":"text","text":"Which section contains the final interpretation? Write ONE word or number.","options":[],"answers":["conclusions"],"explanation":"The lecture uses the word conclusions."}]}]},{"skill":"reading","minutes":60,"parts":[{"id":"reading-p1","title":"One-word gaps","text":"The neighbourhood library project depended on (1) ____ who gave their time freely. At first, the team followed a fixed (2) ____, but the lift was unavailable. Careful (3) ____ showed exactly when the difficulty appeared. The organisers asked visitors for (4) ____ before changing the plan. They also wanted better (5) ____ for people who could not use the first arrangement. In the end, the strongest (6) ____ came from feedback from twenty-six visitors. None of these observations proves that the same approach would work in every town. Nevertheless, the group learned why small, well-recorded changes can matter. Its next meeting will consider whether add a Saturday session is practical and who could help.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-r1-1","type":"text","text":"Complete gap 1 with ONE word.","options":[],"answers":["volunteers"],"explanation":"“volunteers” makes the sentence grammatically and logically complete."},{"id":"m1-r1-2","type":"text","text":"Complete gap 2 with ONE word.","options":[],"answers":["schedule"],"explanation":"“schedule” makes the sentence grammatically and logically complete."},{"id":"m1-r1-3","type":"text","text":"Complete gap 3 with ONE word.","options":[],"answers":["records"],"explanation":"“records” makes the sentence grammatically and logically complete."},{"id":"m1-r1-4","type":"text","text":"Complete gap 4 with ONE word.","options":[],"answers":["feedback"],"explanation":"“feedback” makes the sentence grammatically and logically complete."},{"id":"m1-r1-5","type":"text","text":"Complete gap 5 with ONE word.","options":[],"answers":["access"],"explanation":"“access” makes the sentence grammatically and logically complete."},{"id":"m1-r1-6","type":"text","text":"Complete gap 6 with ONE word.","options":[],"answers":["evidence"],"explanation":"“evidence” makes the sentence grammatically and logically complete."}]},{"id":"reading-p2","title":"Notices and needs","text":"A. Guided introduction: meet Mina at Riverside Library on Thursday.\nB. Quiet hour: a smaller group meets before the main session.\nC. Access help: ask about step-free rooms and larger-print information.\nD. Skills desk: volunteers demonstrate practical methods and tools.\nE. Family visit: activities are planned for adults and children together.\nF. Research corner: examine the report and ask how information was collected.\nG. Follow-up team: help organise add a Saturday session.\nH. Short briefing: Mina gives a twenty-minute overview.\nI. Merchandise desk: souvenirs are available after the event.\nJ. Private room hire: businesses can book an unrelated meeting.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-r2-1","type":"choice","text":"Which notice suits this person? A visitor wants a guided introduction.","options":["B","C","D","E","F","G","H","I","J","A"],"answers":["A"],"explanation":"Notice A offers exactly this service."},{"id":"m1-r2-2","type":"choice","text":"Which notice suits this person? Someone prefers a smaller, quieter group.","options":["C","D","E","F","G","H","I","J","A","B"],"answers":["B"],"explanation":"Notice B offers exactly this service."},{"id":"m1-r2-3","type":"choice","text":"Which notice suits this person? A person needs access information.","options":["D","E","F","G","H","I","J","A","B","C"],"answers":["C"],"explanation":"Notice C offers exactly this service."},{"id":"m1-r2-4","type":"choice","text":"Which notice suits this person? A learner wants a hands-on demonstration.","options":["E","F","G","H","I","J","A","B","C","D"],"answers":["D"],"explanation":"Notice D offers exactly this service."},{"id":"m1-r2-5","type":"choice","text":"Which notice suits this person? A parent wants to bring a child.","options":["F","G","H","I","J","A","B","C","D","E"],"answers":["E"],"explanation":"Notice E offers exactly this service."},{"id":"m1-r2-6","type":"choice","text":"Which notice suits this person? A visitor wants to inspect the evidence.","options":["G","H","I","J","A","B","C","D","E","F"],"answers":["F"],"explanation":"Notice F offers exactly this service."},{"id":"m1-r2-7","type":"choice","text":"Which notice suits this person? A resident wants to help with the next event.","options":["H","I","J","A","B","C","D","E","F","G"],"answers":["G"],"explanation":"Notice G offers exactly this service."},{"id":"m1-r2-8","type":"choice","text":"Which notice suits this person? Someone has only twenty minutes available.","options":["I","J","A","B","C","D","E","F","G","H"],"answers":["H"],"explanation":"Notice H offers exactly this service."}]},{"id":"reading-p3","title":"Paragraph headings","text":"Headings: A. The original difficulty | B. A practical adjustment | C. Collecting information | D. What the figures show | E. A reason for caution | F. The next question | G. A celebrity endorsement | H. An unrelated invention\n\nA. The idea behind neighbourhood library began with sharing books across generations. People welcomed the aim, but the first arrangement was less reliable than the team expected. In particular, the lift was unavailable. Several participants described this as a problem of planning rather than a reason to abandon the work. Their observations were recorded instead of being dismissed.\n\nB. The organisers compared a complicated solution with a manageable one. They chose to move the discussion to the ground floor. This did not remove every difficulty, yet it made the next session possible without asking volunteers to start again. Mina then explained the revised procedure to participants, including those who had missed the first announcement.\n\nC. Good intentions alone could not tell the team whether the change helped. They gathered feedback from twenty-six visitors and kept notes about the conditions under which each observation was made. When a record was incomplete, they marked it as uncertain rather than filling in a likely answer. This made the report less dramatic but more useful.\n\nD. According to the team, attendance rose from eighteen to twenty-six. The figure attracted attention because it described an observable outcome, not merely a prediction. It also encouraged more residents to ask how they could take part. However, a number by itself says little about the people or circumstances behind it.\n\nE. The report acknowledges that the survey covered just one afternoon. A different location, season or group of participants might produce a different result. The team therefore resisted a claim that its method was universally successful. This careful interpretation helped readers separate the evidence from the organisers' hopes.\n\nF. The final recommendation was to add a Saturday session. Before doing so, the organisers want to agree on clear measures of success and an accessible way to collect comments. They also plan to compare a lending shelf with a digital catalogue rather than assuming one choice will be best for every participant.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-r3-1","type":"choice","text":"Choose a heading for paragraph A.","options":["A practical adjustment","Collecting information","What the figures show","A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty"],"answers":["The original difficulty"],"explanation":"Paragraph A develops the idea “the original difficulty”."},{"id":"m1-r3-2","type":"choice","text":"Choose a heading for paragraph B.","options":["Collecting information","What the figures show","A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment"],"answers":["A practical adjustment"],"explanation":"Paragraph B develops the idea “a practical adjustment”."},{"id":"m1-r3-3","type":"choice","text":"Choose a heading for paragraph C.","options":["What the figures show","A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information"],"answers":["Collecting information"],"explanation":"Paragraph C develops the idea “collecting information”."},{"id":"m1-r3-4","type":"choice","text":"Choose a heading for paragraph D.","options":["A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show"],"answers":["What the figures show"],"explanation":"Paragraph D develops the idea “what the figures show”."},{"id":"m1-r3-5","type":"choice","text":"Choose a heading for paragraph E.","options":["The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution"],"answers":["A reason for caution"],"explanation":"Paragraph E develops the idea “a reason for caution”."},{"id":"m1-r3-6","type":"choice","text":"Choose a heading for paragraph F.","options":["A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution","The next question"],"answers":["The next question"],"explanation":"Paragraph F develops the idea “the next question”."}]},{"id":"reading-p4","title":"Detailed article","text":"An invitation to take part in neighbourhood library appeared at Riverside Library. Its stated aim was sharing books across generations. The first public meeting was held on Thursday, and Mina collected the comments. Early reports suggested enthusiasm, but the team also heard practical concerns. Most notably, the lift was unavailable. It would have been easy to present this as a minor inconvenience. Instead, the organisers documented it and chose to move the discussion to the ground floor.\n\nThe revised activity did not follow exactly the original schedule. The organisers tested the change, recorded feedback from twenty-six visitors, and compared comments made before and after the adjustment. Their report states that attendance rose from eighteen to twenty-six. The authors are careful to explain the difference between an observation and a prediction: a positive first month does not guarantee a positive first year.\n\nTwo alternatives were discussed. Some participants supported a lending shelf; others preferred a digital catalogue. Neither option was dismissed without consideration. The report ultimately recommended a limited further trial rather than an immediate permanent decision. Its main reservation was that the survey covered just one afternoon. Mina said that the next stage would be to add a Saturday session.\n\nThe report does not give the ages of the visitors, the exact amount of any future grant, or a date for publishing a second edition. Those details may matter later, but a reader should not invent them now. The value of the project lies partly in its willingness to say what remains unknown.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-r4-1","type":"choice","text":"What was the stated aim of the project?","options":["to sell souvenirs","to replace public transport","to close the venue","sharing books across generations"],"answers":["sharing books across generations"],"explanation":"The opening paragraph states the aim."},{"id":"m1-r4-2","type":"choice","text":"What led the organisers to revise the activity?","options":["a cancelled newspaper","a competition prize","the lift was unavailable","a new mayor"],"answers":["the lift was unavailable"],"explanation":"The reported problem led directly to the adjustment."},{"id":"m1-r4-3","type":"choice","text":"Which action did the organisers take?","options":["ignore accessibility","move the discussion to the ground floor","stop collecting comments","claim guaranteed success"],"answers":["move the discussion to the ground floor"],"explanation":"The revised action is explicitly described."},{"id":"m1-r4-4","type":"choice","text":"How do the authors treat the positive early result?","options":["As useful but limited evidence","As proof for every community","As an error to hide","As irrelevant to the project"],"answers":["As useful but limited evidence"],"explanation":"The text distinguishes observation from prediction."},{"id":"m1-r4-5","type":"choice","text":"True / False / Not Given: The team recorded information during the revised activity.","options":["False","Not Given","True"],"answers":["True"],"explanation":"The second paragraph says the team recorded evidence."},{"id":"m1-r4-6","type":"choice","text":"True / False / Not Given: The organisers permanently rejected both alternatives.","options":["Not Given","True","False"],"answers":["False"],"explanation":"Both alternatives were considered; a further trial was recommended."},{"id":"m1-r4-7","type":"choice","text":"True / False / Not Given: Every visitor was younger than eighteen.","options":["True","False","Not Given"],"answers":["Not Given"],"explanation":"No ages are supplied."},{"id":"m1-r4-8","type":"choice","text":"True / False / Not Given: The report identifies a limitation of the trial.","options":["False","Not Given","True"],"answers":["True"],"explanation":"The report acknowledges a limitation."},{"id":"m1-r4-9","type":"choice","text":"True / False / Not Given: A second edition will be published next month.","options":["Not Given","True","False"],"answers":["Not Given"],"explanation":"No date for a second edition is given."}]},{"id":"reading-p5","title":"Analysis and inference","text":"The organisers at Riverside Library made a useful distinction between a change that is easy to announce and a change that can be evaluated. Their focus was sharing books across generations. During the first stage, the lift was unavailable. The immediate response was to move the discussion to the ground floor, but the team did not describe this response as a complete solution.\n\nTo check what happened, they collected feedback from twenty-six visitors. The report highlighted a figure of 26. A short account of the trial was sent to Mina, who asked for more information about the conditions in which it took place. In particular, the survey covered just one afternoon. This mattered because an impressive number from a narrow trial can be misleading when removed from its context.\n\nAt the next meeting, participants will compare a lending shelf with a digital catalogue. They will also consider how to add a Saturday session. The discussion is designed to invite disagreement supported by reasons, not to reward the loudest speaker. If the group can repeat the trial and explain its limitations clearly, the result will be more useful to other communities.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-r5-1","type":"text","text":"Which venue hosted the organisers? Write ONE word from the venue name.","options":[],"answers":["Riverside"],"explanation":"The venue starts with Riverside."},{"id":"m1-r5-2","type":"text","text":"What figure did the report highlight? Write ONE number.","options":[],"answers":["26"],"explanation":"The figure given is 26."},{"id":"m1-r5-3","type":"text","text":"Who requested more information? Write ONE name.","options":[],"answers":["Mina"],"explanation":"The text names Mina."},{"id":"m1-r5-4","type":"text","text":"What can be misleading without context? Write ONE word.","options":[],"answers":["number"],"explanation":"The passage describes an impressive number from a narrow trial."},{"id":"m1-r5-5","type":"choice","text":"Why does the writer mention the limitation?","options":["To argue that evidence is useless","To avoid hearing from participants","To hide the report","To prevent an overconfident conclusion"],"answers":["To prevent an overconfident conclusion"],"explanation":"The writer warns against removing the result from context."},{"id":"m1-r5-6","type":"choice","text":"What attitude does the final paragraph encourage?","options":["Immediate approval of every idea","Competition for attention","Reasoned disagreement","Silence at meetings"],"answers":["Reasoned disagreement"],"explanation":"The group invites disagreement supported by reasons."}]}]},{"skill":"writing","minutes":60,"parts":[{"id":"writing-p1","title":"Tasks 1.1, 1.2 and 2","text":"Write all three responses. Your work is assessed by an administrator.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-w1","type":"writing","text":"You and a friend attended an activity about neighbourhood library. Write an informal message to your friend. Explain what you enjoyed and suggest one thing to do next. Aim for about 50 words.","options":[],"answers":[],"explanation":""},{"id":"m1-w2","type":"writing","text":"Write to Mina, the organiser at Riverside Library. Explain why you attended, describe the difficulty (“the lift was unavailable”), and suggest a practical improvement. Use a suitable formal tone. Aim for about 120–150 words.","options":[],"answers":[],"explanation":""},{"id":"m1-w3","type":"writing","text":"Some people think communities should invest in a lending shelf; others prefer a digital catalogue. Discuss both views and explain which approach would better support sharing books across generations. Give reasons and examples. Aim for about 180–220 words.","options":[],"answers":[],"explanation":""}]}]},{"skill":"speaking","minutes":15,"parts":[{"id":"speaking-p1","title":"Part 1.1 — personal questions","text":"Record one answer per prompt.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-s1-1","type":"speaking","text":"What do you enjoy doing in your neighbourhood?","options":[],"answers":[],"explanation":""},{"id":"m1-s1-2","type":"speaking","text":"How do you usually learn about local events?","options":[],"answers":[],"explanation":""},{"id":"m1-s1-3","type":"speaking","text":"Have you ever visited a place like Riverside Library?","options":[],"answers":[],"explanation":""}]},{"id":"speaking-p2","title":"Part 1.2 — compare two scenes","text":"Scene A: a small group working together. Scene B: a large public presentation. Compare the two situations.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m1-s2-1","type":"speaking","text":"Compare a small group discussion at Riverside Library with a large public meeting. What might each be like?","options":[],"answers":[],"explanation":""},{"id":"m1-s2-2","type":"speaking","text":"Which setting would help people discuss neighbourhood library more effectively, and why?","options":[],"answers":[],"explanation":""},{"id":"m1-s2-3","type":"speaking","text":"Would your preference change if you were presenting rather than listening?","options":[],"answers":[],"explanation":""}]},{"id":"speaking-p3","title":"Part 2 — extended answer","text":"Prepare for one minute; speak for about two minutes.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questi